#!/bin/bash
set -Eeuo pipefail
umask 077
python3 - <<'PYREMOTE'
import pathlib,os,tempfile,subprocess,shutil,json,base64,gzip
files=json.loads(gzip.decompress(base64.b64decode('')))
d=pathlib.Path(tempfile.mkdtemp(prefix='celikom-metadata97-check-',dir='/tmp'))
try:
 os.chown(d,0,33);os.chmod(d,0o750)
 for name,content in files.items():
  p=d/name;p.parent.mkdir(parents=True,exist_ok=True)
  p.write_text(content);os.chown(p,0,33);os.chmod(p,0o640)
 for p in d.rglob('*'):
  if p.is_dir():os.chown(p,0,33);os.chmod(p,0o750)
 for p in d.rglob('*.php'):
  r=subprocess.run(['runuser','-u','www-data','--','php','-l',str(p)],capture_output=True,text=True,timeout=10)
  if r.returncode:print(r.stdout[:1000],r.stderr[:1000]);raise RuntimeError('PHP_LINT_FAILED')
 r=subprocess.run(['runuser','-u','www-data','--','php',str(d/'server/tests/mp3-metadata.php'),str(d/'fixtures.json')],capture_output=True,text=True,timeout=35)
 print(r.stdout[:4000],end='')
 if r.returncode:print(r.stderr[:4000]);raise RuntimeError('PHP_PARITY_FAILED')
 print('PHP_CANDIDATE_LINT_AND_PARITY_SUCCESS')
finally:shutil.rmtree(d)
PYREMOTE
